pump:sweepBondingCurveFeeAccounts.source:
function sweepBondingCurveFeeAccounts({
  payer,
  mint,
  recipient,
  quoteMint,
  quoteTokenProgram,
}: {
  payer: PublicKey;
  mint: PublicKey;
  recipient: PublicKey;
  quoteMint: PublicKey;
  quoteTokenProgram: PublicKey;
}) {
  const quote = normalizeQuoteMint(quoteMint);
  return {
    payer,
    baseMint: mint,
    quoteMint: quote,
    quoteTokenProgram,
    associatedQuoteBondingCurve: quoteAta(
      bondingCurvePda(mint),
      quote,
      quoteTokenProgram,
    ),
    recipient,
    associatedQuoteRecipient: quoteAta(recipient, quote, quoteTokenProgram),
    eventAuthority: PUMP_EVENT_AUTHORITY_PDA,
    program: PUMP_PROGRAM_ID,
  };
}

