pump:normalizeQuoteMint.source:
export const normalizeQuoteMint = (
  quoteMint: PublicKey | undefined | null,
): PublicKey =>
  !quoteMint || isLegacyQuoteMint(quoteMint) ? NATIVE_MINT : quoteMint;

pump:quoteAta.source:
export const quoteAta = (
  owner: PublicKey,
  quoteMint: PublicKey,
  quoteTokenProgram: PublicKey,
): PublicKey =>
  getAssociatedTokenAddressSync(quoteMint, owner, true, quoteTokenProgram);
